(()=>{
const canvas=document.querySelector('#board'),ctx=canvas.getContext('2d'),economy=window.PixelEconomy;
const tasks=window.PixelTasks;
const roundEl=document.querySelector('#round'),remainingEl=document.querySelector('#remaining'),healthEl=document.querySelector('#health'),status=document.querySelector('#status');
const intro=document.querySelector('#intro-overlay'),upgradeOverlay=document.querySelector('#upgrade-overlay'),gameOverOverlay=document.querySelector('#game-over-overlay');
const W=canvas.width,H=canvas.height,keys={up:false,down:false,left:false,right:false};
let player={x:W/2,y:H/2,r:12},zombies=[],bullets=[],aimAngle=-Math.PI/2,firing=false,round=1,target=6,killed=0,spawned=0,spawnTimer=0,fireTimer=0,health=3,invulnerable=0,playerSpeed=150,reloadTime=.68,bulletsPerShot=1,medkitAvailable=false,state='intro',lastTime=0,raf=0,runKills=0;
function updateTicketButtons(){const available=Boolean(tasks&&tasks.tickets()>0);document.querySelector('#start-run').disabled=!available;document.querySelector('#play-again').disabled=!available;document.querySelector('#restart').disabled=!available}
function updateHud(){roundEl.textContent=round;remainingEl.textContent=Math.max(0,target-killed);healthEl.textContent='♥ '.repeat(health).trim()||'—'}
function startRun(){if(!tasks||!tasks.spendTicket()){status.textContent='Complete a quest on the board to earn an arcade ticket, then come back for a run.';intro.hidden=false;gameOverOverlay.hidden=true;updateTicketButtons();return}round=1;runKills=0;playerSpeed=150;reloadTime=.68;bulletsPerShot=1;aimAngle=-Math.PI/2;firing=false;health=3;medkitAvailable=economy.owns('survivor_medkit');player={x:W/2,y:H/2,r:12};intro.hidden=true;gameOverOverlay.hidden=true;beginRound();updateTicketButtons()}
function beginRound(){target=6+(round-1)*2;killed=0;spawned=0;spawnTimer=.35;fireTimer=.15;zombies=[];bullets=[];state='playing';upgradeOverlay.hidden=true;status.textContent='Round '+round+' is underway. Defeat all '+target+' zombies.';updateHud()}
function chooseUpgrade(which){if(state!=='upgrade')return;if(which==='speed'){playerSpeed+=24;status.textContent='Your movement speed is higher for round '+(round+1)+'.'}else if(which==='reload'){reloadTime=Math.max(.2,reloadTime*.78);status.textContent='Your blaster reloads faster in round '+(round+1)+'.'}else{bulletsPerShot++;status.textContent='Your blaster now fires more bullets per shot in round '+(round+1)+'.'}round++;beginRound()}
function addZombie(){const edge=Math.floor(Math.random()*4);let x,y;if(edge===0){x=Math.random()*W;y=-16}else if(edge===1){x=W+16;y=Math.random()*H}else if(edge===2){x=Math.random()*W;y=H+16}else{x=-16;y=Math.random()*H}zombies.push({x,y,r:13,speed:32+Math.min(28,round*2),hp:1+Math.floor((round-1)/4),hitFlash:0});spawned++}
function fire(){const spread=.14;for(let i=0;i<bulletsPerShot;i++){const offset=(i-(bulletsPerShot-1)/2)*spread,a=aimAngle+offset;bullets.push({x:player.x+Math.cos(a)*17,y:player.y+Math.sin(a)*17,vx:Math.cos(a)*385,vy:Math.sin(a)*385,life:1.35})}}
function finishRound(){state='upgrade';upgradeOverlay.hidden=false;status.textContent='You cleared the wave. Choose one upgrade for the next round.'}
function hitPlayer(zombie){if(invulnerable>0)return;if(zombie){const dx=zombie.x-player.x,dy=zombie.y-player.y,d=Math.hypot(dx,dy)||1;zombie.x+=dx/d*26;zombie.y+=dy/d*26}if(medkitAvailable){medkitAvailable=false;invulnerable=1.15;status.textContent='Your medkit blocked the hit and will be ready again next run.';return}health--;invulnerable=1.2;updateHud();if(health<=0){state='over';upgradeOverlay.hidden=true;gameOverOverlay.hidden=false;document.querySelector('#run-summary').textContent='You defeated '+runKills+' zombies and reached round '+round+'.';status.textContent='The zombies overwhelmed you. Start another run whenever you are ready.'}else status.textContent='You were hit, but still have '+health+' health remaining. Keep moving.'}
function update(dt){if(invulnerable>0)invulnerable=Math.max(0,invulnerable-dt);let dx=(keys.right?1:0)-(keys.left?1:0),dy=(keys.down?1:0)-(keys.up?1:0);if(dx||dy){const mag=Math.hypot(dx,dy);player.x+=dx/mag*playerSpeed*dt;player.y+=dy/mag*playerSpeed*dt;player.x=Math.max(player.r,Math.min(W-player.r,player.x));player.y=Math.max(player.r,Math.min(H-player.r,player.y))}
spawnTimer-=dt;if(spawned<target&&spawnTimer<=0){addZombie();spawnTimer=Math.max(.34,.78-round*.025)}fireTimer-=dt;if(firing&&fireTimer<=0){fire();fireTimer=reloadTime}
for(const z of zombies){const ax=player.x-z.x,ay=player.y-z.y,d=Math.hypot(ax,ay)||1;z.x+=ax/d*z.speed*dt;z.y+=ay/d*z.speed*dt;if(d<player.r+z.r){hitPlayer(z);if(state==='over')return}}
for(const b of bullets){b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;for(const z of zombies){if(z.hp>0&&Math.hypot(z.x-b.x,z.y-b.y)<z.r+4){z.hp--;b.life=0;if(z.hp<=0){killed++;runKills++;economy.award(2);updateHud()}break}}}
bullets=bullets.filter(b=>b.life>0&&b.x>-10&&b.x<W+10&&b.y>-10&&b.y<H+10);zombies=zombies.filter(z=>z.hp>0);if(killed>=target&&spawned>=target&&zombies.length===0)finishRound()}
function draw(){ctx.fillStyle='#182126';ctx.fillRect(0,0,W,H);ctx.strokeStyle='#25343a';ctx.lineWidth=1;for(let x=20;x<W;x+=32){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=20;y<H;y+=32){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}
ctx.fillStyle='#29373a';for(let x=24;x<W;x+=96)for(let y=25;y<H;y+=96){ctx.fillRect(x,y,22,3);ctx.fillRect(x,y,3,20)}
for(const b of bullets){ctx.fillStyle='#d4b18a';ctx.beginPath();ctx.arc(b.x,b.y,3.5,0,Math.PI*2);ctx.fill()}
for(const z of zombies){ctx.fillStyle='#8c716b';ctx.beginPath();ctx.arc(z.x,z.y,z.r,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b28b7d';ctx.beginPath();ctx.arc(z.x-3,z.y-3,3,0,Math.PI*2);ctx.arc(z.x+4,z.y-3,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#293236';ctx.fillRect(z.x-5,z.y+4,10,3)}
if(player){ctx.save();if(invulnerable>0&&Math.floor(invulnerable*12)%2)ctx.globalAlpha=.45;ctx.fillStyle='#0d1518';ctx.beginPath();ctx.ellipse(player.x,player.y+9,13,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#8fc4aa';ctx.beginPath();ctx.arc(player.x,player.y+2,11,0,Math.PI*2);ctx.fill();ctx.fillStyle='#c99d7d';ctx.beginPath();ctx.arc(player.x,player.y-7,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#78aaa4';ctx.fillRect(player.x-8,player.y-13,16,5);ctx.fillStyle='#28353a';ctx.fillRect(player.x-4,player.y-8,2,2);ctx.fillRect(player.x+3,player.y-8,2,2);ctx.strokeStyle='#d4b18a';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(player.x+Math.cos(aimAngle)*8,player.y+Math.sin(aimAngle)*8);ctx.lineTo(player.x+Math.cos(aimAngle)*20,player.y+Math.sin(aimAngle)*20);ctx.stroke();ctx.restore()}}
function frame(now){const dt=Math.min(.05,Math.max(0,(now-lastTime)/1000));lastTime=now;if(state==='playing')update(dt);draw();raf=requestAnimationFrame(frame)}
function handleKey(e,on){const k=e.key.toLowerCase(),map={arrowup:'up',w:'up',arrowdown:'down',s:'down',arrowleft:'left',a:'left',arrowright:'right',d:'right'};if(map[k]){e.preventDefault();keys[map[k]]=on}}
document.addEventListener('keydown',e=>{handleKey(e,true);if(e.code==='Space'){e.preventDefault();firing=true}const aim={i:-Math.PI/2,l:0,k:Math.PI/2,j:Math.PI}[e.key.toLowerCase()];if(aim!==undefined){aimAngle=aim;e.preventDefault()}});document.addEventListener('keyup',e=>{handleKey(e,false);if(e.code==='Space')firing=false});
canvas.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||firing){const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*W/rect.width,y=(e.clientY-rect.top)*H/rect.height;aimAngle=Math.atan2(y-player.y,x-player.x)}});canvas.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();const rect=canvas.getBoundingClientRect(),x=(e.clientX-rect.left)*W/rect.width,y=(e.clientY-rect.top)*H/rect.height;aimAngle=Math.atan2(y-player.y,x-player.x);firing=true;canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointerup',()=>firing=false);canvas.addEventListener('pointercancel',()=>firing=false);
document.querySelectorAll('[data-move]').forEach(button=>{const direction=button.dataset.move;button.addEventListener('pointerdown',e=>{e.preventDefault();button.setPointerCapture(e.pointerId);keys[direction]=true});button.addEventListener('pointerup',()=>keys[direction]=false);button.addEventListener('pointercancel',()=>keys[direction]=false)});document.querySelector('[data-fire]').addEventListener('pointerdown',e=>{e.preventDefault();e.currentTarget.setPointerCapture(e.pointerId);firing=true});document.querySelector('[data-fire]').addEventListener('pointerup',()=>firing=false);document.querySelector('[data-fire]').addEventListener('pointercancel',()=>firing=false);
document.querySelector('#start-run').addEventListener('click',startRun);document.querySelector('#play-again').addEventListener('click',startRun);document.querySelector('#restart').addEventListener('click',startRun);document.querySelectorAll('[data-upgrade]').forEach(button=>button.addEventListener('click',()=>chooseUpgrade(button.dataset.upgrade)));
window.addEventListener('pixelparty:tickets',updateTicketButtons);window.addEventListener('storage',event=>{if(event.key==='pixelPartyArcadeTickets')updateTicketButtons()});
lastTime=performance.now();raf=requestAnimationFrame(frame);updateHud();updateTicketButtons();
})();
